    const cols = l.split("\t");
    return Object.fromEntries(scHeaders.map((h, i) => [h, cols[i] ?? ""]));
  });

  const scStatusChannel = {};
  for (const r of scRows) {
    const k = `${r.status} | ${r["fulfillment-channel"]}`;
    scStatusChannel[k] = (scStatusChannel[k] || 0) + 1;
